/**
 * samlgw2 reconciliation.
 *
 * The gateway keeps one customer per tenant and one IT org per admin-portal
 * org. Tenant and org deletion remove them, but a failed call leaves the
 * file on the gateway. This sweep lists what the gateway has, compares it
 * with the tenant table and deletes what has no owner.
 *
 * Only IT orgs whose id starts with this account's hash are touched: the
 * gateway is shared by several AWS accounts.
 *
 * A customer or IT org is deleted only after it has been an orphan for
 * MIN_ORPHAN_AGE_MS across runs. provision-tenant creates the gateway
 * customer before it writes the tenant record, so a fresh sighting can be a
 * tenant mid-provision, and two runs close together (a dry run followed by
 * the schedule) are not evidence on their own.
 */
import {
  QueryCommand,
  GetItemCommand,
  PutItemCommand,
} from "@aws-sdk/client-dynamodb";
import {
  buildSamlgw2ItorgId,
  hashAwsAccount,
} from "../samlgw2-client/index.mjs";

export const CANDIDATE_KEY = { id: "SAMLGW2#reconcile", configtype: "orphanCandidates" };
export const MIN_ORPHAN_AGE_MS = 60 * 60 * 1000;

/**
 * Pure planning step.
 *
 * @param {Object} input
 * @param {string} input.accountId
 * @param {Array<{orgId: string, itorgId?: string}>} input.orgs
 * @param {Array<{tenantId: string, orgId: string}>} input.tenants
 * @param {Array<{itorgId: string, customers: string[]}>} input.gateway - this account's IT orgs
 * @param {{customers: Record<string,string>, itorgs: Record<string,string>}} input.previous - orphan -> first seen (ISO)
 * @param {number} [input.now]
 */
export function planReconcile({ accountId, orgs, tenants, gateway, previous, now = Date.now() }) {
  const scopePrefix = `${hashAwsAccount(accountId)}-`;
  const lc = (s) => (s || "").toLowerCase();

  const orgItorgs = new Map();
  for (const org of orgs) {
    orgItorgs.set(org.orgId, lc(org.itorgId) || buildSamlgw2ItorgId(accountId, org.orgId));
  }
  const ownedItorgs = new Set(orgItorgs.values());
  // An org whose record predates samlgw2_itorg_id also owns the computed id.
  for (const org of orgs) ownedItorgs.add(buildSamlgw2ItorgId(accountId, org.orgId));

  const ownedCustomers = new Set();
  for (const t of tenants) {
    const itorgId = orgItorgs.get(t.orgId) || buildSamlgw2ItorgId(accountId, t.orgId);
    ownedCustomers.add(`${itorgId}/${lc(t.tenantId)}`);
    ownedCustomers.add(`${buildSamlgw2ItorgId(accountId, t.orgId)}/${lc(t.tenantId)}`);
  }

  const inScope = gateway.filter((g) => lc(g.itorgId).startsWith(scopePrefix));
  const orphanCustomers = [];
  const orphanItorgs = [];
  for (const g of inScope) {
    const itorgId = lc(g.itorgId);
    for (const c of g.customers) {
      const key = `${itorgId}/${lc(c)}`;
      if (!ownedCustomers.has(key)) orphanCustomers.push(key);
    }
    if (!ownedItorgs.has(itorgId)) orphanItorgs.push(itorgId);
  }

  // first-seen carries over from the previous run; a new orphan is stamped now.
  const nowIso = new Date(now).toISOString();
  const firstSeen = (prev, keys) =>
    Object.fromEntries(keys.map((k) => [k, prev?.[k] || nowIso]));
  const seenCustomers = firstSeen(previous?.customers, orphanCustomers);
  const seenItorgs = firstSeen(previous?.itorgs, orphanItorgs);
  const aged = (seen) =>
    Object.keys(seen).filter((k) => now - Date.parse(seen[k]) >= MIN_ORPHAN_AGE_MS);

  return {
    scopePrefix,
    inScopeItorgs: inScope.length,
    inScopeCustomers: inScope.reduce((n, g) => n + g.customers.length, 0),
    ownedCustomers: tenants.length,
    orphanCustomers,
    orphanItorgs,
    candidates: { customers: seenCustomers, itorgs: seenItorgs },
    confirmedCustomers: aged(seenCustomers),
    confirmedItorgs: aged(seenItorgs),
  };
}

async function queryByType(dynamodb, tableName, type) {
  const items = [];
  let ExclusiveStartKey;
  do {
    const page = await dynamodb.send(new QueryCommand({
      TableName: tableName,
      IndexName: "type-created-index",
      KeyConditionExpression: "#type = :type",
      ExpressionAttributeNames: { "#type": "type" },
      ExpressionAttributeValues: { ":type": { S: type } },
      ExclusiveStartKey,
    }));
    items.push(...(page.Items || []));
    ExclusiveStartKey = page.LastEvaluatedKey;
  } while (ExclusiveStartKey);
  return items;
}

async function loadGateway(gateway, accountId) {
  const scopePrefix = `${hashAwsAccount(accountId)}-`;
  const { itorgs = [] } = await gateway.listItOrgs();
  const out = [];
  for (const itorgId of itorgs) {
    if (!itorgId.toLowerCase().startsWith(scopePrefix)) continue;
    const { customers = [] } = await gateway.listCustomers(itorgId);
    out.push({ itorgId, customers: customers.map((c) => c.customer) });
  }
  return out;
}

async function loadPrevious(dynamodb, configTable) {
  const r = await dynamodb.send(new GetItemCommand({
    TableName: configTable,
    Key: { id: { S: CANDIDATE_KEY.id }, configtype: { S: CANDIDATE_KEY.configtype } },
    ConsistentRead: true,
  }));
  return r.Item?.value?.S ? JSON.parse(r.Item.value.S) : { customers: {}, itorgs: {} };
}

async function savePrevious(dynamodb, configTable, plan) {
  await dynamodb.send(new PutItemCommand({
    TableName: configTable,
    Item: {
      id: { S: CANDIDATE_KEY.id },
      configtype: { S: CANDIDATE_KEY.configtype },
      value: { S: JSON.stringify(plan.candidates) },
      updatedAt: { S: new Date().toISOString() },
    },
  }));
}

/**
 * @param {Object} deps
 * @param {boolean} [deps.dryRun=false] - plan and record candidates, delete nothing
 */
export async function runReconcile({
  dynamodb,
  gateway,
  accountId,
  tenantTable,
  configTable,
  dryRun = false,
  logger = console,
}) {
  const [orgItems, tenantItems, gatewayState, previous] = await Promise.all([
    queryByType(dynamodb, tenantTable, "organization"),
    queryByType(dynamodb, tenantTable, "tenant"),
    loadGateway(gateway, accountId),
    loadPrevious(dynamodb, configTable),
  ]);

  const orgs = orgItems.map((i) => ({
    orgId: i.id.S.replace("ORG#", ""),
    itorgId: i.samlgw2_itorg_id?.S,
  }));
  const tenants = tenantItems.map((i) => ({
    tenantId: i.id.S.replace("TENANT#", ""),
    orgId: i.org_id?.S || "",
  }));

  // Zero tenants is a real state (the last tenant was deleted). The orphan
  // age covers both a transient misread and a first tenant mid-provision.
  const plan = planReconcile({ accountId, orgs, tenants, gateway: gatewayState, previous });

  await savePrevious(dynamodb, configTable, plan);

  const deleted = { customers: [], itorgs: [] };
  const failed = [];
  if (!dryRun) {
    for (const key of plan.confirmedCustomers) {
      const [itorgId, customer] = key.split("/");
      try {
        await gateway.deleteCustomer(itorgId, customer);
        deleted.customers.push(key);
      } catch (e) {
        if (e.status === 404) deleted.customers.push(key);
        else failed.push({ key, error: e.message });
      }
    }
    for (const itorgId of plan.confirmedItorgs) {
      try {
        await gateway.deleteItOrg(itorgId);
        deleted.itorgs.push(itorgId);
      } catch (e) {
        if (e.status === 404) deleted.itorgs.push(itorgId);
        else failed.push({ key: itorgId, error: e.message }); // 409: customers remain, next run
      }
    }
  }

  const report = { dryRun, ...plan, deleted, failed };
  logger.info("[samlgw2-reconcile]", JSON.stringify(report));
  return report;
}
