import { DynamoDBClient } from "@aws-sdk/client-dynamodb";
import { createSamlGw2ClientFromEnv } from "../samlgw2-client/index.mjs";
import { runReconcile } from "./reconcile.mjs";

const dynamodb = new DynamoDBClient({ region: process.env.AWS_REGION });

/**
 * Scheduled by EventBridge with { dryRun: false }.
 * One-off inventory: aws lambda invoke ... --payload '{"dryRun":true}'
 */
export const handler = async (event = {}) =>
  runReconcile({
    dynamodb,
    gateway: createSamlGw2ClientFromEnv(),
    accountId: process.env.ACCOUNT_ID,
    tenantTable: process.env.AMFATENANT_TABLE,
    configTable: process.env.CONFIG_TABLE,
    dryRun: event.dryRun === true,
  });
